const body = $('Receive job result').item.json.body;
const q = body.query;
const days = body.days;
const today = days.find(d => d.label === 'today') || {};
const dec = days.find(d => d.label === 'dec21') || {};
const jun = days.find(d => d.label === 'jun21') || {};

function fmtHours(h) {
  if (!h || h === 0) return 'No direct sun';
  const tot = Math.round(h * 60);
  const hrs = Math.floor(tot / 60);
  const mins = tot % 60;
  return (hrs > 0 ? hrs + ' h ' : '') + (mins > 0 ? mins + ' m' : '');
}

function fmtWin(wins) {
  if (!wins || wins.length === 0) return 'No direct sun';
  return wins.map(w => `${w[0]}–${w[1]}`).join(', ');
}

const conf = body.confidence || {};
const html = `☀ <b>Direct sun at your spot</b> — ${q.floor_label}, ${q.facing_label}\n\n<b>Today</b>: ${fmtHours(today.sun_hours)}\n  ${fmtWin(today.windows)}\n<b>Shortest day</b> (Dec 21): ${fmtHours(dec.sun_hours)}\n  ${fmtWin(dec.windows)}\n<b>Longest day</b> (Jun 21): ${fmtHours(jun.sun_hours)}\n  ${fmtWin(jun.windows)}\n\n<b>Confidence: ${conf.label || 'Medium'}</b> — ${conf.pct_est || 50}% of nearby building heights are estimated.\n<i>Not modelled: trees, clouds, balcony overhangs, terrain.</i>\nData © OpenStreetMap contributors`;

return { html: html, chat_id: body.meta.chat_id };
